// SessionsRetrieveDecisionParams holds the parameters of
// Client.Sessions.RetrieveDecision.
type SessionsRetrieveDecisionParams struct {
	// Comma-separated list of extra payload sections. Supported values: `events`
	// and `resubmissions`, alone or together (`events,resubmissions`). When
	// `include=events` is passed, the response additionally contains the session
	// event timeline (`events`, including the `WORKFLOW_BRANCH_EVALUATED` /
	// `WORKFLOW_STATUS_NODE_REACHED` routing events described on the Retrieve
	// Session page), the full activity log (`activity_reviews`), blocklist flags
	// (`blocklisted`), a per-session `cost_breakdown`, workflow metadata
	// (`workflow_type`, `workflow_version`, `workflow_version_id`, and
	// `workflow_terminal_node_id` - the last recorded workflow status node that set
	// a session status, or `null` if none has been recorded; historical provenance
	// that is not cleared by manual approvals, declines or resubmissions, and is
	// replaced by a later workflow status node), and session metadata
	// (`api_service` - string or `null`, set only for standalone-API sessions;
	// `session_type` - `API`, `HOSTED`, or `MIGRATED`; `has_device_nfc_support` -
	// boolean). Two fields change relative to the plain shape: the top-level
	// `session_kind` discriminator is **omitted** (the events shape only exists for
	// user sessions), and the `features` array switches from plain strings to
	// `{feature, node_id}` objects - where the email feature is reported as `EMAIL`
	// instead of `EMAIL_VERIFICATION`. This expanded shape is primarily used by the
	// Didit Console; most API integrations should omit the parameter. **KYB
	// limitation:** `include=events` only applies to user (KYC) sessions. Business
	// sessions (`session_kind = "business"`) always return the standard business
	// decision shape - `events`, `activity_reviews`, `blocklisted`,
	// `cost_breakdown` and the extra `workflow_*`/session metadata are never
	// returned for business sessions, and their `features` array stays a plain
	// string array. With `include=resubmissions` (user and business sessions alike)
	// the response also contains `resubmissions`: one entry per resubmission
	// request, oldest first, each with `number`, `created_at`, `previous_status`,
	// `nodes`, `reasons`, `requested_by` and `results` (what the resubmitted steps
	// returned before the request, under the same keys and in the same shape as the
	// current results). Each `cost_breakdown` item carries `usage_type`, `price`,
	// `details` and `created_at`: a resubmitted step that runs again is billed as a
	// new item.
	Include Opt[SessionsRetrieveDecisionParamsInclude] `json:"-" query:"include"`
}

